// Hand-edited theme settings. Everything else in app/themes/ is generated by scripts/themes/*.mjs.
import { themes, type ThemeId } from './generated';

/** Theme used on first visit, and when a saved theme no longer exists. */
export const DEFAULT_THEME: ThemeId = 'modern-minimal';

/** localStorage key for the chosen site theme. Light/dark is stored separately by next-themes (`theme`). */
export const THEME_STORAGE_KEY = 'doctale-theme';

export const THEME_IDS = themes.map((t) => t.id) as readonly ThemeId[];

// Code colours per site theme: app/themes/code-themes.json (generates app/themes/code.css).
